package org.casbin.jcasbin.log;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class LogRoleTests {

    private DefaultLogger logger;
    private ByteArrayOutputStream outputStream;
    private PrintStream originalOut;

    @Before
    public void setUp() {
        logger = new DefaultLogger();
        outputStream = new ByteArrayOutputStream();
        originalOut = System.out;
        System.setOut(new PrintStream(outputStream));
    }

    @Test
    public void testLogRoleWhenEnabledWithSingleRole() {
        logger.enableLog(true);
        String[] roles = {"admin"};

        logger.logRole(roles);

        String output = outputStream.toString();
        assertTrue("Output should contain role name", output.contains("admin"));
        assertTrue("Output should end with newline", output.endsWith(System.lineSeparator()));
    }

    @Test
    public void testLogRoleWhenEnabledWithMultipleRoles() {
        logger.enableLog(true);
        String[] roles = {"admin", "user", "guest"};

        logger.logRole(roles);

        String output = outputStream.toString();
        assertTrue("Output should contain admin", output.contains("admin"));
        assertTrue("Output should contain user", output.contains("user"));
        assertTrue("Output should contain guest", output.contains("guest"));
        String[] lines = output.split(System.lineSeparator());
        assertEquals("Should have 3 lines for 3 roles", 3, lines.length);
    }

    @Test
    public void testLogRoleWhenEnabledWithEmptyArray() {
        logger.enableLog(true);
        String[] roles = {};

        logger.logRole(roles);

        String output = outputStream.toString();
        assertEquals("Output should be empty for empty array", "", output);
    }

    @Test
    public void testLogRoleWhenDisabled() {
        logger.enableLog(false);
        String[] roles = {"admin", "user"};

        logger.logRole(roles);

        String output = outputStream.toString();
        assertEquals("No output should be produced when disabled", "", output);
    }

    @Test
    public void testLogRoleWhenEnabledWithNullArray() {
        logger.enableLog(true);
        String[] roles = null;

        logger.logRole(roles);

        String output = outputStream.toString();
        assertTrue("Output should contain null representation", output.contains("null"));
    }

    @Test
    public void testLogRoleIdempotentWhenEnabled() {
        logger.enableLog(true);
        String[] roles = {"role1", "role2"};

        logger.logRole(roles);
        String firstOutput = outputStream.toString();

        outputStream.reset();
        logger.logRole(roles);
        String secondOutput = outputStream.toString();

        assertEquals("Multiple calls with same input should produce same output", 
                     firstOutput, secondOutput);
    }

    @Test
    public void testLogRoleDoesNotModifyInputArray() {
        logger.enableLog(true);
        String[] originalRoles = {"admin", "user"};
        String[] rolesCopy = originalRoles.clone();

