import org.mockito.junit.MockitoJUnitRunner;

import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class StartAutoLoadPolicyTests {

    private SyncedEnforcer syncedEnforcer;
    private AtomicInteger autoLoadRunning;

    @Before
    public void setUp() {
        syncedEnforcer = Mockito.spy(new SyncedEnforcer());

        // Use reflection to access the private autoLoadRunning field
        try {
            var field = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
            field.setAccessible(true);
            autoLoadRunning = (AtomicInteger) field.get(syncedEnforcer);
        } catch (Exception e) {
            fail("Failed to access autoLoadRunning field: " + e.getMessage());
        }
    }

    @Test
    public void testStartAutoLoadPolicyStartsThread() throws InterruptedException {
        // Arrange
        long interval = 100L;

        // Act
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit to allow thread to start
        Thread.sleep(50);

        // Assert
        assertEquals(1, autoLoadRunning.get());

        // Clean up - interrupt the thread
        stopAutoLoadThread();
    }

    @Test
    public void testStartAutoLoadPolicyCallsLoadPolicy() throws InterruptedException {
        // Arrange
        long interval = 50L;

        // Act
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait for at least one interval
        Thread.sleep(interval + 20);

        // Assert
        verify(syncedEnforcer, atLeastOnce()).loadPolicy();

        // Clean up
        stopAutoLoadThread();
    }

    @Test
    public void testStartAutoLoadPolicyOnlyOneInstance() throws InterruptedException {
        // Arrange
        long interval = 100L;

        // Act - start first thread
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit for thread to start
        Thread.sleep(50);

        // Try to start second thread
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Assert
        assertEquals(1, autoLoadRunning.get());

        // Clean up
        stopAutoLoadThread();
    }

    @Test
    public void testStartAutoLoadPolicyWithZeroInterval() throws InterruptedException {
        // Arrange
        long interval = 0L;

        // Act
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit
        Thread.sleep(50);

        // Assert - should still start
        assertEquals(1, autoLoadRunning.get());

        // Clean up
        stopAutoLoadThread();
    }

    @Test
    public void testStartAutoLoadPolicyWithNegativeInterval() throws InterruptedException {
        // Arrange
        long interval = -100L;

        // Act
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit
        Thread.sleep(50);

        // Assert - should still start
        assertEquals(1, autoLoadRunning.get());

        // Clean up
        stopAutoLoadThread();
    }

    @Test
    public void testStartAutoLoadPolicyThreadInterruption() throws InterruptedException {
        // Arrange
        long interval = 1000L; // Long interval to ensure thread stays alive

        // Act
        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait for thread to start
        Thread.sleep(50);

        // Assert thread is running
        assertEquals(1, autoLoadRunning.get());

        // Interrupt and wait for thread to stop
        stopAutoLoadThread();

        // Wait a bit more
        Thread.sleep(50);

        // Assert thread has stopped
        assertEquals(0, autoLoadRunning.get());
    }

    @Test
    public void testStartAutoLoadPolicyMultipleCallsAfterStop() throws InterruptedException {
        // Arrange
        long interval = 50L;

        // Act - start and stop multiple times
        for (int i = 0; i < 3; i++) {
            syncedEnforcer.startAutoLoadPolicy(interval);
            Thread.sleep(interval + 20);
            stopAutoLoadThread();
            Thread.sleep(50);
        }

        // Assert - verify loadPolicy was called multiple times
        verify(syncedEnforcer, atLeast(3)).loadPolicy();
    }

    private void stopAutoLoadThread() {
        try {
            // Use reflection to access and interrupt the auto-load thread
            var field = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
            field.setAccessible(true);
            AtomicInteger running = (AtomicInteger) field.get(syncedEnforcer);

            // Set to 0 to simulate thread stopping
            running.set(0);

            // Also try to find and interrupt any running threads
            Thread[] threads = new Thread[Thread.activeCount()];
            Thread.enumerate(threads);
            for (Thread thread : threads) {
                if (thread != null && thread.getName().contains("AutoLoad")) {
                    thread.interrupt();
                }
            }
        } catch (Exception e) {
            // Ignore reflection exceptions in test cleanup
        }
    }
}

