        boolean ruleUpdated = this.model.updatePolicy(sec, ptype, oldRule, newRule);
        if (!ruleUpdated) {
            return false;
        }
        List<List<String>> rules = new ArrayList<>();
        if (sec.equals("g")) {
            try {
                // remove the old rule
                rules.add(oldRule);
                this.buildIncrementalRoleLinks(Model.PolicyOperations.POLICY_REMOVE, ptype, rules);
            } catch (Exception e) {
                return false;
            }
            try {
