                this.buildIncrementalRoleLinks(Model.PolicyOperations.POLICY_ADD, ptype, noExistsPolicy);
            } catch (Exception e) {
                Util.logPrint("An exception occurred:" + e.getMessage());
                return noExistsPolicy;
            }
        }
        System.out.println();
        return rules;
    }

