        verify(roleManager).addLink(name1, name2, domain);
        verify(roleManager).addLink(name1, name2, matchingDomain1);
        verify(roleManager).addLink(name1, name2, matchingDomain2);
        verify(roleManager, never()).addLink(name1, name2, nonMatchingDomain);
        verify(domainMatchingFunc, times(3)).test(anyString(), anyString());
    }

